window.products.push({"id":1094840,"name":"Enesco Jim Shore Heartwood Creek Margaritaville Santa Musical","category":"homeandappliances","retail price":85.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/81Ebq+IOzOL._AC_SL1500_.jpg","description":"Take a trip to Margaritaville with Jim Shore’s collection of tropical figurines. Santa takes a much-needed vacation in this handcrafted design, guitar, and the margarita in hand. The 10” musical figurine plays the classic hit song, “Margaritaville.”","images":["https://m.media-amazon.com/images/I/81Ebq+IOzOL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Enesco","source_asin":"B0798HNXQB","category_path":"Home & Kitchen"},"sku":"BM-1094840","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0798HNXQB","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0798HNXQB","price_pending":true,"merchant_ready":false});
